// Polaris web components JSX type declarations
// These custom elements are loaded at runtime by polaris.js (CDN script tag).
// TypeScript doesn't know about them out of the box.

declare namespace JSX {
  interface IntrinsicElements {
    "s-page": any;
    "s-section": any;
    "s-card": any;
    "s-badge": any;
    "s-button": any;
    "s-table": any;
    "s-select": any;
    "s-option": any;
    "s-text-field": any;
    "s-password-field": any;
    "s-number-field": any;
    "s-checkbox": any;
    "s-stack": any;
    "s-banner": any;
    "s-empty-state": any;
    "s-text": any;
    "s-progress": any;
    "s-spinner": any;
    "s-app-nav": any;
    "s-app-nav-item": any;
    "s-link": any;
    "s-list": any;
    "s-list-item": any;
    "s-tabs": any;
    "s-tab": any;
    "s-divider": any;
    "s-box": any;
    "s-grid": any;
    "s-thumbnail": any;
    "s-search-field": any;
    "s-email-field": any;
    "s-url-field": any;
    "s-radio": any;
    "s-textarea": any;
    "s-toggle": any;
    "s-scroll-trigger": any;
    "s-button-group": any;
    "s-paragraph": any;
    "s-unordered-list": any;
    "s-table-header-row": any;
    "s-table-row": any;
    "s-table-cell": any;
  }
}
